var card = event["cards"][0]
player.show_card(card, target)
var result = await target.choose(["同意", "拒绝"], "是否同意交易？")
if result == "同意":
	var cards2 = await target.choose_card(1, "hand")
	if cards2.size() > 0:
		var card2 = cards2[0]
		player._remove_card_from_zone(card)
		target._remove_card_from_zone(card2)
		target.hand.append(card)
		player.hand.append(card2)
